#!/usr/bin/env python3
"""Turn a graph blob into a C header the targets compile in.

The target chains cannot open files, so the blob travels as bytes. Bytes rather than
float literals on purpose: a literal would have to be re-parsed by the target's libc,
and `1e-7` round-tripping is exactly the kind of thing that silently differs between
newlib and glibc (the same reason `emit_kat_image.py` keeps raw bytes).

This is what makes the case real rather than staged: the **same file** the host gtest
reads is the one the Cortex-M parses, so "it ran on the target" cannot mean "a
hand-maintained C array that used to match the model".

Usage: emit_blob_image.py [--name kat_k2_blob] <model.blob> <out.h>
"""
import argparse
import hashlib
import pathlib
import sys

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
import blobfmt  # noqa: E402  (the format lives in one file; this is that file's neighbour)

MAGIC = b"INFRKAT\0"


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("blob")
    ap.add_argument("out")
    ap.add_argument("--name", default="kat_blob", help="C identifier of the array")
    ap.add_argument("--segment", action="store_true",
                    help="emit an .incbin assembly file instead of a C array; for a blob "
                         "too big to spell out as bytes (the 1.4 MB MobileNet one)")
    args = ap.parse_args()

    data = pathlib.Path(args.blob).read_bytes()
    if data[:8] != MAGIC:
        print(f"emit_blob_image: {args.blob} is not an INFRKAT blob", file=sys.stderr)
        return 1
    (version,) = [int.from_bytes(data[8:12], "little")]
    # Both versions travel the same way: this file's job is bytes in, bytes out, so it must not
    # grow a second opinion about which versions exist. The readers are the ones that care.
    #
    # 两个版本走同一条路：本文件的职责是字节进、字节出，所以它不该长出"哪些版本存在"的第二套
    # 判断。在乎版本的是读取器。
    if version not in (blobfmt.VERSION_V2, blobfmt.VERSION):
        print(f"emit_blob_image: unsupported version {version} "
              f"(expected {blobfmt.VERSION_V2} or {blobfmt.VERSION})", file=sys.stderr)
        return 1

    upper = args.name.upper()
    # The arena size is **derived here, from the blob**, not typed in: the executors
    # compute the same figure themselves, and the KAT asserts the two agree on every
    # target. Baking it is what turns "the plan says 180 KB" into something a red test
    # can defend.
    #
    # 这里的 arena 大小**从 blob 推出来**，不是手写的：两份执行器各自算同一个数，KAT 在
    # 每个目标上断言两者相等。把计划值烘进来，"计划说 180 KB"才变成一条能变红的断言能守住
    # 的东西。
    # A v3 blob is sized in bytes because an int8 slot is one byte per element; a v2 blob is sized
    # in floats because every slot in it is fp32. The downstream arithmetic is the same, only the
    # unit changes -- which is why this reads the version instead of assuming one.
    #
    # v3 blob 按字节定尺寸（int8 槽每元素一字节），v2 按 float（里面每个槽都是 fp32）。下游算
    # 法相同，只是单位变了——所以这里读版本，而不是假定。
    if version == blobfmt.VERSION:
        counts, _dtypes, refs, ops = blobfmt.layout_bytes(data)
        unit = "bytes"
    else:
        counts, refs, ops = blobfmt.layout(data)
        unit = "floats"
    arena = blobfmt.plan_arena(counts, refs)
    in_floats, out_floats = blobfmt.endpoints(counts, refs, ops)
    # FNV-1a folded to 8 bits. `blob_graph.c` recomputes it over the bytes it actually
    # parsed, so a stale `.incbin` (right length, wrong file) is caught on the target
    # instead of producing eight targets that agree about the wrong model.
    #
    # FNV-1a 折到 8 位。`blob_graph.c` 会对它真正解析到的字节重算一遍，于是过期的
    # `.incbin`（长度对、文件错）在目标端就会被抓住，而不是让八个目标一致地跑错模型。
    fold = 2166136261
    for byte in data:
        fold = ((fold ^ byte) * 16777619) & 0xFFFFFFFF
    out = [
        "/* Generated by .github/project/qa/prep/emit_blob_image.py -- do not edit.",
        f" * {pathlib.Path(args.blob).name} as bytes: the target parses this with",
        " * .github/project/qa/kat/blob_graph.c, the same blob the host gtest reads.",
        " * 由 .github/project/qa/prep/emit_blob_image.py 生成，不要手改。 */",
        "#pragma once",
        "",
        f"#define {upper}_LEN {len(data)}u",
        f'#define {upper}_SHA256 "{hashlib.sha256(data).hexdigest()}"',
        f"#define {upper}_ARENA {arena}u",
        f"#define {upper}_IN_FLOATS {in_floats}u",
        f"#define {upper}_OUT_FLOATS {out_floats}u",
        f"#define {upper}_HASH8 0x{fold & 0xFF:02X}u",
        "",
    ]
    if args.segment:
        # `.incbin` instead of a 1.4 MB brace-initialised array: the C spelling of that
        # blob is ~7 MB of source, and every target build would pay to parse it. The
        # section/alignment are plain GNU as, which is what all our toolchains are --
        # no `.type @object`, because that directive's sigil differs between the host
        # (x86-64, `@`) and the cross targets (`%`).
        #
        # 用 `.incbin` 而不是 1.4 MB 的花括号数组：那份 C 源约 7 MB，每个目标构建都要解析一遍。
        # 段与对齐都是 GNU as 的通用写法，不写 `.type @object`——那条指令的符号在宿主（x86-64
        # 用 `@`）与交叉目标（用 `%`）之间不一致。
        out.append(f"extern const unsigned char {args.name}[];")
        out.append("")
        asm = [
            "/* Generated by .github/project/qa/prep/emit_blob_image.py -- do not edit. */",
            "    .section .rodata",
            "    .balign 8",
            f"    .globl {args.name}",
            f"{args.name}:",
            f'    .incbin "{pathlib.Path(args.blob).resolve().as_posix()}"',
        ]
        asm_path = pathlib.Path(args.out).with_suffix(".S")
        asm_path.parent.mkdir(parents=True, exist_ok=True)
        asm_path.write_text("\n".join(asm) + "\n", encoding="utf-8")
        print(f"[emit_blob_image] wrote {asm_path} (.incbin, {len(data)} B)")
    else:
        out.append(f"static const unsigned char {args.name}[{upper}_LEN] = {{")
        row = []
        for byte in data:
            row.append(f"0x{byte:02X}")
            if len(row) == 12:
                out.append("    " + ", ".join(row) + ",")
                row = []
        if row:
            out.append("    " + ", ".join(row) + ",")
        out.append("};")
        out.append("")

    target = pathlib.Path(args.out)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("\n".join(out), encoding="utf-8")
    print(f"[emit_blob_image] wrote {target} ({len(data)} B, arena {arena} floats)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
